// HDS supplied 2026-10-21: p.7 section 1.2 explicitly references FIPS 197.
// Constants below are from FIPS 197 (2001), Appendix C.1 and C.3, not OpenSSL
// and not output generated by the model. No reset/address/timing policy is used.
// https://nvlpubs.nist.gov/nistpubs/fips/nist.fips.197.pdf
#include "fu3/aes/aes_core.h"
#include <systemc>
#include <iostream>
#include <stdexcept>
#include <string>

int sc_main(int argc, char** argv) {
    const std::string test = argc == 2 ? argv[1] : "";
    try {
        using namespace fu3::aes;
        const Block plaintext{0x00,0x11,0x22,0x33,0x44,0x55,0x66,0x77,
                              0x88,0x99,0xaa,0xbb,0xcc,0xdd,0xee,0xff};
        const Block ciphertext128{0x69,0xc4,0xe0,0xd8,0x6a,0x7b,0x04,0x30,
                                  0xd8,0xcd,0xb7,0x80,0x70,0xb4,0xc5,0x5a};
        const Block ciphertext256{0x8e,0xa2,0xb7,0xca,0x51,0x67,0x45,0xbf,
                                  0xea,0xfc,0x49,0x90,0x4b,0x49,0x60,0x89};
        Key key{0x00,0x01,0x02,0x03,0x04,0x05,0x06,0x07,
                0x08,0x09,0x0a,0x0b,0x0c,0x0d,0x0e,0x0f,
                0x10,0x11,0x12,0x13,0x14,0x15,0x16,0x17,
                0x18,0x19,0x1a,0x1b,0x1c,0x1d,0x1e,0x1f};
        const bool wide = test == "encrypt256" || test == "decrypt256";
        const bool encrypt = test == "encrypt128" || test == "encrypt256" || test == "upper_key128";
        if (!wide && test != "encrypt128" && test != "decrypt128" && test != "upper_key128")
            throw std::invalid_argument("unknown SPEC scenario");
        AesCore core;
        const auto& ciphertext = wide ? ciphertext256 : ciphertext128;
        unsigned checks = 0;
        const unsigned variants = test == "upper_key128" ? 256 : 1;
        for (unsigned pattern = 0; pattern < variants; ++pattern) {
            if (test == "upper_key128")
                for (unsigned i = 16; i < 32; ++i) key[i] = static_cast<std::uint8_t>(pattern);
            core.initialize(key, wide);
            const auto got = core.transform(encrypt ? plaintext : ciphertext, encrypt);
            if (got != (encrypt ? ciphertext : plaintext)) {
                std::cerr << "SPEC_FAIL " << test << " HDS=p.7/10/11/16; FIPS197=C.1/C.3"
                          << " pattern=" << pattern << '\n';
                return 1;
            }
            ++checks;
        }
        std::cout << "SPEC_PASS " << test << " checks=" << checks
                  << " scope=core-only source=HDS:p7,10,11,16+FIPS197:C.1/C.3\n";
        return 0;
    } catch (const std::exception& e) {
        // Infrastructure/API failures are not an observed mismatch with a SPEC expected value.
        std::cerr << "TEST_ERROR " << test << ": " << e.what() << '\n';
        return 2;
    }
}
